<div id="sdNewModal"></div><script>
(()=>{'use strict';const $=id=>document.getElementById(id),BASE='..';let data=[],desde='',hasta='',coord='todos',tipo='todos',impacto='todos',mes=new Date(),sem=new Date();const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const inicio=d=>{const x=new Date(d.getFullYear(),d.getMonth(),d.getDate());x.setDate(x.getDate()-((x.getDay()+6)%7));return x};const fmt=f=>{const [y,m,d]=String(f||'').split('-');return d?`${d}/${m}/${y}`:'-'};const nom=d=>d.toLocaleDateString('es-PE',{month:'long',year:'numeric'}).replace(/^./,x=>x.toUpperCase());const txtTipo=x=>x==='suspension'?'Suspension':'Amonestacion escrita';const actualizar=()=>{$('sdMes').textContent=nom(mes);const a=inicio(sem),b=new Date(a);b.setDate(b.getDate()+6);$('sdSem').textContent=`${fmt(iso(a))} - ${fmt(iso(b))}`};const render=()=>{const list=data.filter(x=>(!desde||x.fecha_incidencia>=desde)&&(!hasta||x.fecha_incidencia<=hasta)&&(coord==='todos'||x.aplicado_por===coord)&&(tipo==='todos'||x.tipo_sancion===tipo)&&(impacto==='todos'||x.impacto===impacto));$('sdCount').textContent=`${list.length} sanciones`;const rows=$('sdRows'),mobile=$('sdMobile');rows.innerHTML='';mobile.innerHTML='';if(!list.length){rows.innerHTML='<tr><td class="sd-empty" colspan="6">No hay sanciones con estos filtros.</td></tr>';mobile.innerHTML='<div class="sd-empty">No hay sanciones con estos filtros.</div>';return}list.forEach(x=>{const chip=`<span class="sd-chip ${x.tipo_sancion==='suspension'?'susp':'warn'}">${txtTipo(x.tipo_sancion)}</span>`;rows.insertAdjacentHTML('beforeend',`<tr data-sref="${x.incidencia_id}"><td><div class="sd-name">${esc(x.colaborador_nombre)}</div><div class="sd-sub">${esc(x.colaborador_cargo||'-')}</div></td><td>${chip}</td><td><div class="sd-name">${esc(x.punto_mejorar)}</div><div class="sd-sub">${x._manual ? 'Registro manual' : `R