();aplicarMes()};$('sdSemPrev').onclick=()=>{sem=new Date(sem.getFullYear(),sem.getMonth(),sem.getDate()-7);actualizar();aplicarSem()};$('sdSemNext').onclick=()=>{sem=new Date(sem.getFullYear(),sem.getMonth(),sem.getDate()+7);actualizar();aplicarSem()};$('sdDesde').onchange=e=>{desde=e.target.value;render()};$('sdHasta').onchange=e=>{hasta=e.target.value;render()};$('sdCoord').onchange=e=>{coord=e.target.value;render()};$('sdTipo').onchange=e=>{tipo=e.target.value;render()};$('sdImpacto').onchange=e=>{impacto=e.target.value;render()};$('sdClear').onclick=()=>{desde=hasta='';coord=tipo=impacto='todos';['sdDesde','sdHasta'].forEach(id=>$(id).value='');['sdCoord','sdTipo','sdImpacto'].forEach(id=>$(id).value='todos');render()};load().catch(()=>{$('sdCount').textContent='Error de red'})})();
</script><script>(()=>{let cur=null,path='',records=[];const $=id=>document.getElementById(id),modal=$('sdModal'),esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const decorate=()=>document.querySelectorAll('#sdRows tr').forEach(tr=>{if(tr.dataset.done)return;const id=tr.dataset.sref||(tr.textContent.match(/Registro #(\d+)/)||[])[1],x=records.find(r=>String(r.incidencia_id)===id);if(!x)return;tr.dataset.done='1';const td=tr.children;td[2].innerHTML+=x.incidencia_declaracion_path?`<div class="sd-sub"><a href="../${esc(x.incidencia_declaracion_path)}" target="_blank">Ver declaracion anexada</a></div>`:'<div class="sd-sub">Sin declaracion anexada</div>';td[3].innerHTML=`<div class="sd-name">${esc(x.fecha_inicio||'Sin fecha')} - ${esc(x.fecha_fin||'Sin fecha')}</div><div class="sd-sub">${Number(x.dias_sancion||0)} dia(s)</div>`;td[4].innerHTML=x.evidencia_path?`<a href="../${esc(x.evidencia_path)}" target="_blank">Ver evidencia</a>`:'Sin evidencia';td[5].innerHTML=`<button data-sd="edit" data-id="${x.id}" data-ini="${x.fecha_inicio||''}" data-fin="${x.fecha_fin||''}" data-evid="${x.evidencia_path||''}">Editar</button> <button data-sd="del" data-id="${x.id}">Eliminar</button>`});fetch('../api/get_sanciones_disciplinarias.php').then(r=>r.json()).then(j=>{records=(j.data||[]).map(x=>Object.assign({},x,{_manual:!x.incidencia_id,incidencia_id:x.incidencia_id||x.id}));decorate();new MutationObserver(decorate).observe($('sdRows'),{childList:true})});document.addEventListener('click',async e=>{const b=e.target.closest('[data-sd]');if(!b)return;if(b.dataset.sd==='edit'){cur=b.dataset;path=cur.evid||'';$('sdEditIni').value=cur.ini||'';$('sdEditFin').value=cur.fin||'';modal.style.display='flex'}if(b.dataset.sd==='del'&&confirm('Eliminar esta sancion? La incidencia volvera a Sin medida aplicada.')){let r=await fetch('../api/delete_sancion_disciplinaria.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:+b.dataset.id})}),j=await r.json();if(j.success)location.reload();else alert(j.error||'No se pudo eliminar')}});$('sdCancel').onclick=()=>modal.style.display='none';$('sdEditFile').onchange=async e=>{let f=e.target.files[0];if(!f)return;let fd=new FormData();fd.append('file',f);let r=await fetch('../api/upload_sancion_evidencia.php',{method:'POST',body:fd}),j=await r.json();if(j.success)path=j.path;else alert(j.error)};$('sdSave').onclick=async()=>{let r=await fetch('../api/save_sancion_disciplinaria.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:+cur.id,fecha_inicio:$('sdEditIni').value,fecha_fin:$('sdEditFin').value,evidencia_path:path})}),j=await r.json();if(j.success)location.reload();else alert(j.error||'No se pudo guardar')}})();</script></body></html>
